-- Every change to a record, for automations. A save that changes nothing, or only a deal's place in
-- its kanban column, is not a change. `crm.actor` names who made it (records.ts sets it).
CREATE FUNCTION "crm"."emit_record_event"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  old_row jsonb;
  new_row jsonb;
BEGIN
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;
  IF TG_OP = 'UPDATE' AND (old_row - 'updated_at' - 'index') = (new_row - 'updated_at' - 'index') THEN
    RETURN NULL;
  END IF;
  INSERT INTO "crm"."record_events" ("object", "record_id", "action", "old", "new", "actor")
  VALUES (
    TG_TABLE_NAME,
    COALESCE((new_row->>'id')::bigint, (old_row->>'id')::bigint),
    CASE TG_OP WHEN 'INSERT' THEN 'created' WHEN 'UPDATE' THEN 'updated' ELSE 'deleted' END,
    old_row,
    new_row,
    NULLIF(current_setting('crm.actor', true), '')
  );
  RETURN NULL;
END;
$$;
--> statement-breakpoint
